=== FILE: tb/debounce_rca_tb.v ===
`timescale 1ns / 1ps
module debounce_rca_tb;
    reg  clk   = 1'b0;
    reg  rst   = 1'b1;
    reg  noisy = 1'b0;
    wire clean;

    debounce #(.STABLE(4)) dut (
        .clk  (clk),
        .rst  (rst),
        .noisy(noisy),
        .clean(clean)
    );

    always #5 clk = ~clk;

    integer passed = 0;
    integer failed = 0;
    integer i;
    reg [8*64-1:0] nonce;
    reg saw_high;
    reg saw_low;

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
            nonce = "none";

        // Reset
        repeat (3) @(negedge clk);
        rst = 1'b0;
        repeat (6) @(negedge clk);

        // Check 1: 2-edge high pulse must be filtered
        saw_high = 1'b0;
        noisy = 1'b1;
        @(negedge clk); if (clean) saw_high = 1'b1;
        @(negedge clk); if (clean) saw_high = 1'b1;
        noisy = 1'b0;
        for (i = 0; i < 8; i = i + 1) begin
            @(negedge clk); if (clean) saw_high = 1'b1;
        end
        if (!saw_high) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $display("FAIL check1: 2-edge high pulse reached clean");
        end

        // Check 2: long high settles clean to 1
        noisy = 1'b1;
        repeat (12) @(negedge clk);
        if (clean === 1'b1) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $display("FAIL check2: clean=%b after long high, expected 1", clean);
        end

        // Check 3: 2-edge low pulse after settling high must be filtered
        saw_low = 1'b0;
        noisy = 1'b0;
        @(negedge clk); if (clean !== 1'b1) saw_low = 1'b1;
        @(negedge clk); if (clean !== 1'b1) saw_low = 1'b1;
        noisy = 1'b1;
        for (i = 0; i < 8; i = i + 1) begin
            @(negedge clk); if (clean !== 1'b1) saw_low = 1'b1;
        end
        if (!saw_low) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $display("FAIL check3: 2-edge low pulse reached clean (falling change did not restart count)");
        end

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===
